assert(null, "default");
assert("", "blank");
assert("a", "a");
assert("b", "b");
assert("c", "c");
assert("no");
assert("yes");
assert("four");
assert("blurb");
assert("hello");
assert("lamps");
assert("lambs");
assert("names");
assert("slurp");
assert("towed");
assert("words");
assert("not", "default");
assert("other", "default");
assert("y", "default");
assert("longer example", "default");
System.Console.Write("RAN");

void assert(string input, string expected = null)
{
    if (C.M(input) != (expected ?? input))
    {
        throw new System.Exception($"{input} produced {C.M(input)}");
    }
}

public class C
{
    public static string M(string o)
    {
        return o switch
        {
            "" => "blank",
            "a" => "a",
            "b" => "b",
            "c" => "c",
            "no" => "no",
            "yes" => "yes",
            "four" => "four",
            "alice" => "alice",
            "blurb" => "blurb",
            "hello" => "hello",
            "lamps" => "lamps",
            "lambs" => "lambs",
            "lower" => "lower",
            "names" => "names",
            "slurp" => "slurp",
            "towed" => "towed",
            "words" => "words",
            _ => "default"
        };
    }
}
